// /api/v1/step-images/[key] — GET: serve a step image (P21).
// Keys are uuid+ext generated by saveFile, so the URL never expires and the
// content never changes → public + immutable caching. Same repo-relative
// storage root as pamphlet attachments (UPLOADS_DIR override in tests).
import { readFile } from "@/lib/server/storage";
import { fail } from "@/lib/server/http";

const EXT_TYPES: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  gif: "image/gif",
};

export async function GET(_req: Request, { params }: { params: Promise<{ key: string }> }) {
  const { key } = await params;
  // the key must be a stored filename: uuid + short ext — refuse traversal
  if (!/^[0-9a-f-]{36}\.[a-z0-9]{1,8}$/i.test(key)) return fail("تصویر پیدا نشد", 404);

  try {
    const buffer = await readFile(key, "step-images");
    const type = EXT_TYPES[key.split(".").pop()?.toLowerCase() ?? ""] ?? "application/octet-stream";
    return new Response(new Uint8Array(buffer), {
      status: 200,
      headers: {
        "Content-Type": type,
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": "public, max-age=31536000, immutable", // uuid-keyed content
      },
    });
  } catch {
    return fail("تصویر پیدا نشد", 404);
  }
}
